r.post('/p/:pid/requests/import', async (c) => {
  const a = await project(c);
  requireProject(a, 'request.create');
  requireOpen(a);
  const b = await body(c);
  const source: Source = SOURCES.find((s) => s === b.source && s !== 'portal') ?? 'other';
  const items = (Array.isArray(b.items) ? b.items : []).slice(0, 51) as Record<string, unknown>[];
  if (!items.length) throw bad('옮길 메시지를 하나 이상 골라 주세요.');
  if (items.length > 50) throw bad('한 번에 50개까지 옮길 수 있습니다.');
  const list = items.map((it) => ({ title: cleanLine(it.title, 120), text: cleanText(it.text, 4000), author: cleanLine(it.author, 40), at: cleanLine(it.at, 40) }));
  if (list.some((x) => !x.title)) throw bad('고른 메시지마다 제목이 있어야 합니다.');
  const d = db(c);
  const scope = await confirmedScope(c.env, a.project.id);
  const first = await withNumber(c.env, 'requests', a.project.id, async (start) => {
    const now = Date.now();
    const tx = new Tx(c.env);
    list.forEach((it, i) => {
      const id = newId();
      tx.add(
        d.insert(schema.requests).values({
          id,
          projectId: a.project.id,
          number: start + i,
          title: it.title,
          status: 'new',
          scopeVersionId: scope?.id ?? null,
          source,
          sourceText: it.text,
          sourceAuthor: it.author,
          sourceAt: it.at,
          createdBy: a.user.id,
          createdAt: now,
          updatedAt: now,
        }),
      );
      audit(tx, d, {
        workspaceId: a.workspace.id,
        projectId: a.project.id,
        actor: a.actor,
        action: 'request_imported',
        subject: { type: 'request', id },
        visibility: 'public',
        summary: `요청 #${start + i} ‘${it.title}’ 등록 (붙여 넣은 ${SOURCE_LABEL[source]} 원문${it.author ? ` · ${it.author}` : ''}${it.at ? ` · ${it.at}` : ''})`,
        at: now,
      });
    });
    await tx.commit();
    return start;
  });
  return c.json({ first, count: list.length }, 201);
});

async function loadRequest(c: Ctx) {
  const a = await project(c);
  const n = Number(c.req.param('n'));
  if (!Number.isInteger(n) || n < 1) throw notFound();
  const req = await db(c).query.requests.findFirst({ where: and(eq(schema.requests.projectId, a.project.id), eq(schema.requests.number, n)) });
  if (!req) throw notFound();
  return { a, req };
}

